SELECT analytics_order_facts.channel, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year IN (2026, 2022) AND analytics_order_facts.region = 'West' AND analytics_order_facts.customer_segment = 'small_business' AND analytics_order_facts.category = 'category_04' AND analytics_order_facts.payment_method = 'bank_transfer' GROUP BY analytics_order_facts.channel ORDER BY analytics_order_facts.channel ASC LIMIT 24
